async function main() {
  const inspectIds = ['1:473','1:495','49:130','49:141','1:196','1:204','1:214'];
  const desc = (n, depth=0) => {
    if (!n || depth>6) return null;
    const o = { name: n.name, type: n.type };
    if ('textCharacters' in n) o.text = n.textCharacters;
    if (n.children) o.children = n.children.map(c=>desc(c, depth+1)).filter(Boolean);
    return o;
  };
  const out = {};
  inspectIds.forEach(id=>{
    const n = figma.getNodeById(id);
    out[id] = n ? desc(n) : 'MISSING';
  });
  return out;
}
