async function main() {
  const splash = figma.getNodeById('200:2');
  splash.children.filter(c=>c.name.indexOf('PROBE')===0).forEach(c=>c.remove());

  // Traverse whole document looking for target media names
  const targets = ['Splash_Burger_Stack','Burger_Cheeseburger_Wendys','Burger_Veggie','Burger_Chicken','Burger_Fried_Chicken','Burger_Exploded_Custom'];
  const found = [];
  function walk(n, depth){
    if(depth>40) return;
    if (targets.indexOf(n.name)>=0) {
      found.push(n.name+'@'+n.id+':'+n.type);
    }
    if ('children' in n && n.children) {
      for (const c of n.children) walk(c, depth+1);
    }
  }
  walk(figma.root, 0);
  const m = figma.createText();
  m.name='SEARCH_'+(found.length?found.join(' | '):'NONE');
  m.characters='x';
  splash.appendChild(m);
}
